import re

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections = {}  # Include DEFAULT section and others
    current_section = None
    pending_key = None  # Track last key for continuation

    def interpolate(s: str, current_section_name: str, sections_dict, path=None):
        if path is None:
            path = set()
        res = []
        i = 0

        while i < len(s):
            if s[i] == '$' and i < len(s) - 1 and s[i+1] == '{':
                j = s.find('}', i + 2)
                if j == -1:
                    raise ValueError(f"Unclosed variable {s[i:]}")
                var_str = s[i+2:j]
                i = j + 1
                if ':' in var_str:
                    sec_part, key_part = var_str.split(':', 1)
                else:
                    sec_part, key_part = None, var_str
                sec = sec_part if sec_part is not None else current_section_name
                key_part = key_part.strip()

                if (sec, key_part) in path:
                    raise ValueError("Circular reference detected")

                new_path = set(path)
                new_path.add((sec, key_part))

                if sec not in sections_dict:
                    raise KeyError(f"Section {sec} not found")

                sec_dict = sections_dict[sec]
                if key_part in sec_dict:
                    val = sec_dict[key_part]
                elif sec == current_section_name and 'DEFAULT' in sections_dict and key_part in sections_dict['DEFAULT']:
                    val = sections_dict['DEFAULT'][key_part]
                else:
                    raise KeyError(f"Key {key_part} not found in {sec}")

                new_val = interpolate(val, sec, sections_dict, new_path)
                res.append(new_val)
            else:
                res.append(s[i])
                i += 1
        return ''.join(res)

    for line in text.split('\n'):
        stripped = line.strip()
        if not stripped or stripped[0] in ('#', ';'):
            continue

        section_line = stripped.startswith('[') and stripped.endswith(']')

        if section_line:
            section_name = stripped[1:-1].strip()
            current_section = section_name
            if current_section not in sections:
                sections[current_section] = {}
            pending_key = None
            continue

        if current_section is None:
            raise ValueError("Key-value line before any section header")

        is_continuation = len(line) != len(line.lstrip())

        if is_continuation:
            if pending_key is None:
                raise ValueError("Continuation line has no preceding key")
            cont_text = line.strip()
            sections[current_section][pending_key] += "\n" + cont_text
        else:
            eq_pos = line.find('=')
            colon_pos = line.find(':')

            split_char = '=' if (eq_pos != -1 and (colon_pos == -1 or eq_pos < colon_pos)) else (':' if colon_pos != -1 else None)

            if split_char is None:
                raise ValueError(f"Malformed line: {line}")

            key_part = line.split(split_char)[0].strip().lower()
            value_part = line.split(split_char, 1)[1].strip()

            if value_part.startswith('"'):
                end_quote = value_part.find('"', 1)
                if end_quote == -1:
                    val = value_part[1:]
                else:
                    val = value_part[1:end_quote]
                value_part = val
            else:
                comment_pos = len(value_part)
                for c in (';', '#'):
                    idx = value_part.find(' ' + c)
                    if idx != -1 and idx < comment_pos:
                        comment_pos = idx
                if comment_pos != len(value_part):
                    value_part = value_part[:comment_pos].strip()

            sections[current_section][key_part] = value_part
            pending_key = key_part

    # Perform interpolation
    for sec_name in list(sections.keys()):
        sec_dict = sections[sec_name]
        for key in list(sec_dict.keys()):
            try:
                new_val = interpolate(sec_dict[key], sec_name, sections)
            except KeyError as e:
                raise KeyError(f"Malformed reference in interpolation for {sec_name}.{key}: {e}") from e
            except ValueError as e:
                raise ValueError(f"Invalid interpolation cycle in {sec_name}.{key}: {e}") from e
            sec_dict[key] = new_val

    # Build the result dict, excluding DEFAULT
    result = {}
    for sec_name in sections:
        if sec_name == 'DEFAULT':
            continue
        merged = {}
        if 'DEFAULT' in sections:
            merged.update(sections['DEFAULT'])
        merged.update(sections[sec_name])
        result[sec_name] = merged

    return result
