from collections import OrderedDict
from typing import Callable, Dict, Any

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock: Callable[[], float]):
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._entries: OrderedDict[Any, tuple] = OrderedDict()
        self._stats: Dict[str, int] = {
            'hits': 0,
            'misses': 0,
            'evictions': 0,
            'expirations': 0
        }

    def put(self, key, value):
        if self._capacity == 0:
            return
        now = self._clock()
        new_expiry = now + self._ttl

        if key in self._entries:
            del self._entries[key]
        else:
            expired = []
            for k in list(self._entries.keys()):
                _, exp = self._entries[k]
                if exp <= now:
                    expired.append(k)
            for k in expired:
                del self._entries[k]
            self._stats['expirations'] += len(expired)
            if len(self._entries) >= self._capacity:
                if self._entries:
                    lru_key = next(iter(self._entries))
                    del self._entries[lru_key]
                    self._stats['evictions'] += 1
        self._entries[key] = (value, new_expiry)

    def get(self, key, default=None):
        if self._capacity == 0:
            self._stats['misses'] += 1
            return default
        now = self._clock()
        if key not in self._entries:
            self._stats['misses'] += 1
            return default
        val, exp = self._entries[key]
        if now >= exp:
            del self._entries[key]
            self._stats['expirations'] += 1
            self._stats['misses'] += 1
            return default
        else:
            self._stats['hits'] += 1
            del self._entries[key]
            self._entries[key] = (val, exp)
            return val

    def __len__(self):
        if self._capacity == 0:
            return 0
        now = self._clock()
        cnt = 0
        for _, exp in self._entries.values():
            if exp > now:
                cnt += 1
        return cnt

    def stats(self):
        return dict(self._stats)
