import re

def parse_duration(s: str) -> int:
    s_cleaned = s.strip().replace(" ", "")
    if not s_cleaned:
        raise ValueError("Empty string")

    if not re.fullmatch(r'^(\d+[hmsHMS])+$', s_cleaned):
        raise ValueError("Invalid format")

    parts = []
    for match in re.finditer(r'(\d+)([hmsHMS])', s_cleaned):
        num_str, unit_str = match.group(1), match.group(2).lower()
        parts.append((num_str, unit_str))

    units = [unit for _, unit in parts]
    if len(units) != len(set(units)):
        raise ValueError("Repeated units")

    order = {'h': 0, 'm': 1, 's': 2}
    previous_order = -1
    for unit in units:
        current_order = order[unit]
        if current_order < previous_order:
            raise ValueError("Units are not in order")
        previous_order = current_order

    total_seconds = 0
    for num_str, unit in parts:
        value = int(num_str)
        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        else:
            total_seconds += value

    return total_seconds
