def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""
    unique_sorted = sorted(set(nums))
    parts = []
    if not unique_sorted:
        return ""
    start = unique_sorted[0]
    end = start
    for num in unique_sorted[1:]:
        if num == end + 1:
            end = num
        else:
            length = end - start + 1
            if length >= 3:
                parts.append(f"{start}..{end}")
            else:
                for n in range(start, end + 1):
                    parts.append(str(n))
            start = num
            end = num
    # Process the final run
    length = end - start + 1
    if length >= 3:
        parts.append(f"{start}..{end}")
    else:
        for n in range(start, end + 1):
            parts.append(str(n))
    return ','.join(parts)
