def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    customer_data = {}

    for row in rows:
        customer = row.get("customer", "").strip()
        if not customer:
            continue
        amount_str = row.get("amount", "")
        processed_str = amount_str.replace("$", "").replace(",", "")
        try:
            amount = float(processed_str)
        except ValueError:
            continue

        key = customer.lower()
        if key not in customer_data:
            customer_data[key] = {
                "name": customer,
                "total": 0.0,
            }
        customer_data[key]["total"] += amount

    customer_list = [
        (entry["name"], round(entry["total"], 2))
        for entry in customer_data.values()
    ]

    customer_list.sort(key=lambda x: (-x[1], x[0]))

    return customer_list[:n]
